/** Decor fields of a world asset (none for breakables). */
interface WorldFields {
	readonly layer?: DecorLayer;
	readonly glow?: boolean;
	readonly emissive?: boolean;
	/** Copy the art's outline(s) (decor pieces). */
	readonly outline?: boolean;
}

/** A world art asset from its layout, or undefined while its file has no ID. */
function worldAsset(
	layout: ValeWorldLayout,
	ids: AssetIds,
	fields: WorldFields,
): ImageAsset | SpriteSetAsset | undefined {
	if (layout.kind === "image") {
		const assetId = ids[layout.file];
		if (assetId === undefined) return undefined;
		const image: ImageAsset = {
			kind: "image",
			assetId: assetId as ImageAsset["assetId"],
			w: layout.w,
			h: layout.h,
			pivot: { x: layout.pivot.x, y: layout.pivot.y },
			pixelsPerTile: layout.pixelsPerTile,
		};
		if (layout.rect !== undefined) image.rect = deepClone(layout.rect);
		if (fields.outline === true && layout.outline !== undefined) image.outline = deepClone(layout.outline);
		if (fields.layer !== undefined) image.layer = fields.layer;
		if (fields.glow === true) image.glow = true;
		if (fields.emissive === true) image.emissive = true;
		return image;
	}
	const sheets = new Array<SpriteSheetImage>();
	for (const sheet of layout.sheets) {
		const assetId = ids[sheet.file];
		if (assetId === undefined) return undefined;
		sheets.push({ assetId: assetId as SpriteSheetImage["assetId"], w: sheet.w, h: sheet.h });
	}
	const set: SpriteSetAsset = {
		kind: "sprites",
		frameW: layout.frameW,
		frameH: layout.frameH,
		pivot: { x: layout.pivot.x, y: layout.pivot.y },
		pixelsPerTile: layout.pixelsPerTile,
		resample: layout.resample,
		facings: { count: layout.facings.count, zeroDeg: layout.facings.zeroDeg, ccw: layout.facings.ccw },
		sheets,
		animations: deepClone(layout.animations),
	};
	if (fields.outline === true && layout.outlines !== undefined) set.outlines = deepClone(layout.outlines);
	if (fields.layer !== undefined) set.layer = fields.layer;
	if (fields.glow === true) {
		set.glow = true;
		if (layout.glowAt !== undefined) set.glowAt = { x: layout.glowAt.x, y: layout.glowAt.y };
	}
	if (fields.emissive === true) set.emissive = true;
	return set;
}

/** The world art layout named `art` (a programming error, not a missing upload, when absent). */
function worldLayout(art: string): ValeWorldLayout {
	const layout = VALE_WORLD_LAYOUTS[art];
	if (layout === undefined) error(`vale: no world art "${art}" in layout.ts (art/atlases.json worldArt.pieces)`, 0);
	return layout;
}

/** Decor pieces and effects, ambient textures and breakables onto `manifest` (see the file comment). */
function addWorldArt(manifest: ThemeManifest, ids: AssetIds): void {
	for (const b of BIOMES) {
		for (const piece of VALE_DECOR_PIECES) {
			const asset = worldAsset(worldLayout(piece.art), ids, {
				layer: piece.layer,
				glow: piece.glow,
				outline: piece.layer === "tall" || piece.layer === "low",
			});
			if (asset !== undefined) manifest.assets[decorId(b.id, piece.kind, piece.variant)] = asset;
		}
		for (const piece of VALE_VOID_DECOR_PIECES) {
			const layout = VALE_WORLD_LAYOUTS[piece.art];
			if (layout === undefined) continue; // not built yet (see VALE_VOID_DECOR_PIECES)
			const asset = worldAsset(layout, ids, {
				layer: piece.layer,
				outline: piece.layer === "tall" || piece.layer === "low",
			});
			if (asset !== undefined) manifest.assets[decorId(b.id, piece.kind, piece.variant)] = asset;
		}
		for (const piece of VALE_VOID_KIND_PIECES) {
			const asset = worldAsset(worldLayout(piece.art), ids, {
				layer: piece.layer,
				outline: piece.layer === "tall" || piece.layer === "low",
			});
			if (asset !== undefined) manifest.assets[voidDecorId(b.id, piece.voidKind, piece.variant)] = asset;
		}
		const mote = worldLayout(VALE_AMBIENT_ART.art);
		const assetId = mote.kind === "image" ? ids[mote.file] : undefined;
		if (mote.kind === "image" && assetId !== undefined) {
			const ambient: ImageAsset = {
				kind: "image",
				assetId: assetId as ImageAsset["assetId"],
				w: mote.w,
				h: mote.h,
			};
			if (VALE_AMBIENT_ART.emissive[b.id]) ambient.emissive = true;
			manifest.assets[decorAmbientId(b.id)] = ambient;
		}
	}
	for (const name of DECOR_FX_NAMES) {
		const asset = worldAsset(worldLayout(VALE_DECOR_FX[name]), ids, { emissive: true });
		if (asset !== undefined) manifest.assets[decorFxId(name)] = asset;
	}
	for (const kind of BREAKABLE_KINDS) {
		const asset = worldAsset(worldLayout(VALE_BREAKABLE_ART[kind]), ids, {});
		if (asset !== undefined) manifest.assets[breakableId(kind)] = asset;
	}
	for (const kind of PELLET_KINDS) {
		const asset = worldAsset(worldLayout(VALE_PELLET_ART[kind]), ids, {});
		if (asset !== undefined) manifest.assets[pelletId(kind)] = asset;
	}
	for (const id of TREASURE_IDS) {
		const art = VALE_TREASURE_ART[id];
		if (art === undefined) continue;
		const asset = worldAsset(worldLayout(art), ids, {});
		if (asset !== undefined) manifest.assets[id] = asset;
	}
}

/** A sound from its layout, or undefined (the placeholder's SILENT stays) while any of its files has no ID. */
function soundAsset(layout: ValeSoundLayout, ids: AssetIds): SoundAsset | undefined {
	const clips = new Array<SoundAsset["assetId"]>();
	for (const file of layout.files) {
		const assetId = ids[file];
		if (assetId === undefined) {
			return undefined;
		}
		clips.push(assetId as SoundAsset["assetId"]);
	}
	if (clips.size() === 0) {
		return undefined;
	}
	const sound: SoundAsset = { kind: "sound", assetId: clips[0], volume: layout.volume };
	const variants = new Array<SoundAsset["assetId"]>();
	for (let i = 1; i < clips.size(); i++) {
		variants.push(clips[i]);
	}
	if (variants.size() > 0) {
		sound.variants = variants;
	}
	if (layout.pitch !== undefined) {
		sound.pitch = [layout.pitch[0], layout.pitch[1]];
	}
	if (layout.minInterval !== undefined) {
		sound.minInterval = layout.minInterval;
	}
	return sound;
}

/** The UI icon atlas (docs/UI_ART.md UA3 / UA4): its file, size and pieces (uiIconLayout.ts as generated). */
export interface ValeUiIconSource {
	/** The atlas file (the key of its uploaded ID in assetIds.ts). */
	readonly file: string;
	/** The atlas size, pixels. */
	readonly atlas: { readonly w: number; readonly h: number };
	/** ui id -> its rect (and pivot) in the atlas. */
	readonly icons: Readonly<Record<string, ValeUiIconLayout>>;
}

/** The icon atlas as generated (uiIconLayout.ts). */
export const VALE_UI_ICON_SOURCE: ValeUiIconSource = {
	file: VALE_UI_ICON_FILE,
	atlas: VALE_UI_ICON_ATLAS,
	icons: VALE_UI_ICONS,
};

/**
 * The UI icons (contract.ts uiIconIds) of one uploaded icon atlas: every piece of `icons` as an `image` of the whole
 * atlas (`assetId`, `atlas` w / h) with its `rect` and `pivot`. All or nothing: no `assetId` (the atlas is not uploaded
 * yet), no icons. Pure (a fresh object every call); exported for the specs, which feed a synthetic layout.
 */
export function valeUiIconImages(
	icons: Readonly<Record<string, ValeUiIconLayout>>,
	atlas: { readonly w: number; readonly h: number },
	assetId: string | undefined,
): Record<string, ImageAsset> {
	const out: Record<string, ImageAsset> = {};
	if (assetId === undefined) {
		return out;
	}
	for (const id of sortedKeys(icons)) {
		const piece = icons[id];
		const r = piece.rect;
		const image: ImageAsset = {
			kind: "image",
			assetId: assetId as ImageAsset["assetId"],
			w: atlas.w,
			h: atlas.h,
			rect: { x: r.x, y: r.y, w: r.w, h: r.h },
		};
		if (piece.pivot !== undefined) {
			image.pivot = { x: piece.pivot.x, y: piece.pivot.y };
		}
		out[id] = image;
	}
	return out;
}

/**
 * The required ui ids that draw a UI skin piece once the pack has it (docs/UI_ART.md Architecture 2): the generic panel
 * is the in-run panel, the health / mana / ember icons the full heart, the full flask and the candle. Until then they
 * stay the placeholder's.
 */
export const VALE_UI_REQUIRED_ART: Readonly<Record<string, string>> = {
	"ui.panel": "ui.panel.hud",
	"ui.icon.health": "ui.heart.full",
	"ui.icon.mana": "ui.flask.full",
	"ui.icon.ember": "ui.candle",
};

/** Layouts buildValeManifest reads, for the specs; each one absent = the generated one. */
export interface ValeLayoutSources {
	/** VALE_IMAGE_LAYOUTS. */
	readonly images?: Readonly<Record<string, ValeImageLayout>>;
	/** VALE_UI_ICON_SOURCE. */
	readonly uiIcons?: ValeUiIconSource;
}

/**
 * The vale manifest for a map of uploaded IDs (art/build file name -> `rbxassetid://<digits>`). Pure and
 * deterministic: a fresh copy of the placeholder manifest every call, never mutating it. `sources` swaps in synthetic
 * layouts (specs only).
 */
export function buildValeManifest(ids: AssetIds = VALE_ASSET_IDS, sources: ValeLayoutSources = {}): ThemeManifest {
	const images = sources.images ?? VALE_IMAGE_LAYOUTS;
	const uiIcons = sources.uiIcons ?? VALE_UI_ICON_SOURCE;
	const manifest = deepClone(PLACEHOLDER_MANIFEST);
	manifest.id = "vale";
	manifest.name = "Vale";
	manifest.version = "0.1.0";

	for (const id of sortedKeys(VALE_SPRITE_LAYOUTS)) {
		manifest.assets[id] = valeSpriteAsset(id, VALE_SPRITE_LAYOUTS[id], ids) ?? { kind: "placeholder" };
	}
	const optional = new Set([...draftSkinIds(), ...uiSkinIds()]);
	for (const id of sortedKeys(images)) {
		const layout = images[id];
		const assetId = ids[layout.file];
		if (assetId === undefined) {
			// an optional draft skin image (docs/DRAFT_REVEAL.md DR3) or UI skin piece (docs/UI_ART.md UA4) is simply
			// absent: the overlay / primitive draws the flat look
			if (!optional.has(id)) {
				manifest.assets[id] = { kind: "placeholder" };
			}
			continue;
		}
		const image: ImageAsset = {
			kind: "image",
			assetId: assetId as ImageAsset["assetId"],
			w: layout.w,
			h: layout.h,
		};
		if (layout.tilesPerImage !== undefined) {
			image.tilesPerImage = layout.tilesPerImage;
		}
		if (layout.pivot !== undefined) {
			image.pivot = { x: layout.pivot.x, y: layout.pivot.y };
		}
		if (layout.pixelsPerTile !== undefined) {
			image.pixelsPerTile = layout.pixelsPerTile;
		}
		if (layout.slice !== undefined) {
			const sl = layout.slice;
			image.slice = { left: sl.left, top: sl.top, right: sl.right, bottom: sl.bottom };
		}
		manifest.assets[id] = image;
	}
	// The UI icon atlas (docs/UI_ART.md UA4): every icon once uploaded, none before.
	const icons = valeUiIconImages(uiIcons.icons, uiIcons.atlas, ids[uiIcons.file]);
	for (const id of sortedKeys(icons)) {
		manifest.assets[id] = icons[id];
	}
	for (const id of sortedKeys(VALE_UI_REQUIRED_ART)) {
		const art = manifest.assets[VALE_UI_REQUIRED_ART[id]];
		if (art !== undefined && art.kind === "image") {
			manifest.assets[id] = deepClone(art);
		}
	}
	addWorldArt(manifest, ids);

	for (const biomeId of sortedKeys(manifest.biomes)) {
		const materials = VALE_BIOME_MATERIALS[biomeId as BiomeId];
		if (materials === undefined) {
			continue;
		}
		const biome = manifest.biomes[biomeId];
		const out: BiomeMaterials = deepClone(materials) as BiomeMaterials;
		const floorTile = manifest.assets[biome.tiles.floor];
		if (floorTile !== undefined && floorTile.kind === "image" && floorTile.tilesPerImage !== undefined) {
			out.floor = undefined; // a textured floor stays SmoothPlastic (DEFAULT_BIOME_MATERIAL)
		}
		biome.materials = out;
	}

	for (const id of sortedKeys(VALE_SOUND_LAYOUTS)) {
		const sound = soundAsset(VALE_SOUND_LAYOUTS[id], ids);
		if (sound !== undefined) {
			manifest.assets[id] = sound;
		}
	}

	// Sprite effects and ambient particle textures (docs/FX_AUDIO.md F2, F6; fx.ts): optional slots, so an entry
	// without its uploaded PNG is simply absent (nothing drawn).
	const fx = valeFxAssets(ids);
	for (const id of sortedKeys(fx)) {
		manifest.assets[id] = fx[id];
	}
	// An ambient ID the R5 world art already filled (addWorldArt: the Lords of Pain mote, once decor-mote.png has an
	// ID) keeps it; the Ninja Adventure flipbook (F6) is the fallback for a biome the mote does not cover yet.
	const ambient = valeAmbientAssets(ids);
	for (const id of sortedKeys(ambient)) {
		if (manifest.assets[id] === undefined) {
			manifest.assets[id] = ambient[id];
		}
	}

	const floor = images[VALE_FLOOR_TEXTURE_ID];
	if (floor !== undefined && ids[floor.file] !== undefined) {
		for (const biomeId of sortedKeys(manifest.biomes)) {
			const biome = manifest.biomes[biomeId];
			if (biome.tiles.floor === VALE_FLOOR_TEXTURE_ID) {
				biome.floor = VALE_FLOOR_HEX;
			}
		}
	}
	return manifest;
}

/** The pack as bundled (THEME_PACKS.vale): the IDs pasted into assetIds.ts. */
export const VALE_MANIFEST: ThemeManifest = buildValeManifest();
